function validate([text]) {
  if (typeof text !== 'string' || text.length < 1 || text.length > 2000) return 'text needs 1 to 2000 letters.';
  if (!/^[a-z]+$/.test(text)) return 'text may contain only lowercase English letters.';
  return null;
}

