function distinctEchoSubstrings(text) {
  const n = text.length;
  const codes = Array.from(text, (letter) => letter.charCodeAt(0));
  let previous = new Array(n).fill(0);
  let current = new Array(n).fill(0);
  let count = 0;
  for (let end = 0; end < n; end++) {
    let longest = 0;
    for (let other = 0; other < end; other++) {
      if (codes[other] === codes[end]) {
        const length = other > 0 ? previous[other - 1] + 1 : 1;
        current[other] = length;
        if (length > longest) {
          longest = length;
        }
      } else {
        current[other] = 0;
      }
    }
    for (let half = Math.floor(longest / 2) + 1; half <= longest && 2 * half <= end + 1; half++) {
      if (current[end - half] >= half) {
        count++;
      }
    }
    [previous, current] = [current, previous];
  }
  return count;
}

