function distinctEchoSubstrings(text) {
  const echoes = new Set();
  for (let i = 0; i < text.length; i++) {
    for (let j = i + 2; j <= text.length; j += 2) {
      const piece = text.slice(i, j);
      const mid = piece.length / 2;
      if (piece.slice(0, mid) === piece.slice(mid)) echoes.add(piece);
    }
  }
  return echoes.size;
}

