function generate(rand, size) {
  const pick = (k) => Math.floor(rand() * k);
  const letters = 'abcdefghijklmnopqrstuvwxyz';
  const n = size === 'large' ? 1500 + pick(501) : 1 + pick(14);
  const alphabet = 1 + pick(size === 'large' ? 26 : 4);
  const shape = pick(3);
  if (shape === 0) {
    // Plain random letters from a small alphabet.
    let text = '';
    for (let i = 0; i < n; i++) text += letters[pick(alphabet)];
    return [text];
  }
  // A short block repeated, with a few letters changed, to create many echoes.
  const blockLength = 1 + pick(size === 'large' ? 12 : 4);
  let block = '';
  for (let i = 0; i < blockLength; i++) block += letters[pick(alphabet)];
  const chars = [];
  for (let i = 0; i < n; i++) chars.push(block[i % blockLength]);
  const changes = shape === 1 ? 0 : 1 + pick(size === 'large' ? 20 : 2);
  for (let c = 0; c < changes; c++) chars[pick(n)] = letters[pick(alphabet)];
  return [chars.join('')];
}
